{
    "name": "acme/blog",
    "description": "A simple blog application",
    "type": "project",
    "license": "MIT",
    "require": {
        "php": ">=8.2",
        "ext-pdo": "*",
        "ext-mbstring": "*",
        "monolog/monolog": "^3.5",
        "slim/slim": "^4.12",
        "doctrine/orm": "^2.15"
    },
    "require-dev": {
        "phpunit/phpunit": "^10.5",
        "pestphp/pest": "^2.30",
        "squizlabs/php_codesniffer": "^3.8",
        "phpstan/phpstan": "^1.10"
    },
    "autoload": {
        "psr-4": {
            "Acme\\Blog\\": "src/"
        },
        "files": ["src/helpers.php"]
    },
    "autoload-dev": {
        "psr-4": {
            "Acme\\Blog\\Tests\\": "tests/"
        }
    },
    "scripts": {
        "test": "pest",
        "lint": "phpcs src",
        "stan": "phpstan analyse src",
        "post-autoload-dump": [
            "Acme\\Blog\\Installer::postInstall"
        ]
    },
    "config": {
        "platform": {"php": "8.2"},
        "optimize-autoloader": true,
        "sort-packages": true
    }
}
